export class ActionWindowController {
  private cursor = 0;
  private statuses = new Map<string, ActionStatus>();
  constructor(readonly plan: FullActionPlan) {
    if (!plan.steps.length) throw new Error('EMPTY_PLAN');
    for (const step of plan.steps) this.statuses.set(step.stepId, 'PENDING');
    this.statuses.set(plan.steps[0].stepId, 'READY');
  }
  currentWindow(): ActionWindow {
    const current = this.plan.steps[this.cursor];
    if (!current) throw new Error('PLAN_COMPLETED');
    const prev = this.cursor > 0 ? this.plan.steps[this.cursor-1] : null;
    const next = this.cursor + 1 < this.plan.steps.length ? this.plan.steps[this.cursor+1] : null;
    return {
      windowId: `${this.plan.planId}:${current.stepId}`,
      planId: this.plan.planId,
      previous: prev ? {stepId:prev.stepId,summary:prev.summary ?? `${prev.action} ${prev.target}`,result:this.statuses.get(prev.stepId)!} : null,
      current,
      next: next ? {stepId:next.stepId,summary:next.summary ?? `${next.action} ${next.target}`} : null,
      actionBudget: 1,
      cursor: this.cursor
    };
  }
  begin(stepId: string): void {
    const current = this.plan.steps[this.cursor];
    if (current.stepId !== stepId) throw new Error('OUT_OF_ORDER_ACTION');
    if (this.statuses.get(stepId) !== 'READY') throw new Error('ACTION_NOT_READY');
    this.statuses.set(stepId,'EXECUTING');
  }
  complete(stepId: string, result: Extract<ActionStatus,'PASSED'|'FAILED'|'AMBIGUOUS'>): void {
    const current = this.plan.steps[this.cursor];
    if (current.stepId !== stepId) throw new Error('OUT_OF_ORDER_COMPLETION');
    if (this.statuses.get(stepId) !== 'EXECUTING') throw new Error('ACTION_NOT_EXECUTING');
    this.statuses.set(stepId,result);
    if (result === 'PASSED') {
      this.cursor += 1;
