nst next = this.plan.steps[this.cursor];
      if (next) this.statuses.set(next.stepId,'READY');
    }
  }
  isComplete(): boolean { return this.cursor >= this.plan.steps.length; }
  status(stepId:string): ActionStatus | undefined { return this.statuses.get(stepId); }
}

