import type { Page } from 'playwright';

export const transferHtml = `<!doctype html>
<html><head><meta charset="utf-8"><title>Transfer Demo</title></head>
<body>
<main data-page-id="customer.transfer.create" data-page-state="READY">
  <label for="beneficiary">收款人</label>
  <select id="beneficiary" data-testid="transfer-beneficiary" aria-label="收款人">
    <option value="">请选择</option><option value="customer.bob">测试客户乙</option>
  </select>
  <label for="amount">转账金额</label>
  <input id="amount" data-testid="transfer-amount" aria-label="转账金额" />
  <button data-testid="transfer-confirm" aria-label="确认转账">确认转账</button>
  <div data-testid="transfer-status" role="status"></div>
</main>
<script>
  document.querySelector('[data-testid="transfer-confirm"]').addEventListener('click', async () => {
    const beneficiary = document.querySelector('#beneficiary').value;
    const amount = document.querySelector('#amount').value;
    const response = await fetch('https://bank.test/api/v1/transfers', {
      method: 'POST',
      headers: {'content-type':'application/json','x-correlation-id':'CORR-P0C'},
      body: JSON.stringify({beneficiary, amount:{currency:'CNY', value:amount}})
    });
    const body = await response.json();
    document.querySelector('[data-testid="transfer-status"]').textContent =
      body.status === 'SETTLED' ? '转账成功' : '转账失败';
  });
</script>
</body></html>`;

export async function prepareTransferPage(page: Page): Promise<void> {
  await page.route('https://bank.test/api/v1/transfers', async route => {
    const request = route.request();
    const payload = request.postDataJSON();
    const ok = payload?.beneficiary === 'customer.bob' && payload?.amount?.value === '100.00';
    await route.fulfill({
      status: ok ? 201 : 422,
      contentType: 'application/json',
      body: JSON.stringify(ok
        ? {id:'TR-P0C-001', status:'SETTLED', correlationId:'CORR-P0C'}
        : {code:'INVALID_INPUT', status:'FAILED'})
    });
  });
  await page.setContent(transferHtml, { waitUntil: 'domcontentloaded' });
}

